#!/usr/bin/env python3
"""Bounded source import, cache/Git equivalence and tamper rejection. New temporary output only."""
import argparse,hashlib,importlib.util,json,subprocess,tempfile,tracemalloc
from pathlib import Path
root=Path(__file__).resolve().parent.parent
spec=importlib.util.spec_from_file_location('hit_importer',root/'scripts/import-source-hit-animations.py');imp=importlib.util.module_from_spec(spec);spec.loader.exec_module(imp)
p=argparse.ArgumentParser();p.add_argument('output',type=Path);a=p.parse_args();out=a.output.resolve();out.mkdir(parents=True,exist_ok=False)
ref=Path((root/'.tools/reference-root').read_text().strip());source=imp.authenticated(ref);expected=imp.build(ref);checks=[]
def need(ok,why):
 if not ok:raise AssertionError(why)
 checks.append(why)
def reject(action,why):
 try:action()
 except ValueError:checks.append(why);return
 raise AssertionError('Expected rejection: '+why)
with tempfile.TemporaryDirectory(prefix='hit-import-test-') as t:
 temp=Path(t);cache=temp/'source';cache.mkdir()
 for name,data in source.items():
  path=cache/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(data)
 need(imp.build(cache)==expected,'authenticated source cache and fixed Git blob builds have byte-identical output')
 for name,data in source.items():
  path=cache/name;changed=bytearray(data);changed[len(changed)//2]^=1;path.write_bytes(changed)
  reject(lambda:imp.build(cache),'same-length source corruption rejected: '+name);path.write_bytes(data)
 sparse=cache/'graphics/battle_anims/sprites/impact.png'
 with sparse.open('wb') as f:f.truncate(1<<30)
 tracemalloc.start();reject(lambda:imp.build(cache),'1GiB sparse asset rejected by fstat before allocation');_,peak=tracemalloc.get_traced_memory();tracemalloc.stop();need(peak<5_000_000,'oversized source guard peak Python memory below 5MB');sparse.write_bytes(source['graphics/battle_anims/sprites/impact.png'])
 # Corruption must fail before creating either generated directory.
 sparse.write_bytes(b'bad');publish=temp/'publish'
 r=subprocess.run(['python3',root/'scripts/import-source-hit-animations.py',cache,publish],capture_output=True,text=True,timeout=30);need(r.returncode!=0 and not publish.exists(),'CLI source rejection publishes no generated output');sparse.write_bytes(source['graphics/battle_anims/sprites/impact.png'])
 r=subprocess.run(['python3',root/'scripts/import-source-hit-animations.py',cache,publish],capture_output=True,text=True,timeout=30);need(r.returncode==0,'CLI authenticated regeneration succeeds')
 for folder,files in expected.items():
  for name,blob in files.items():
   need((publish/folder/name).read_bytes()==blob,'CLI output retains exact authenticated build bytes: '+folder+'/'+name)
   need((root/'content/generated'/folder/name).read_bytes()==blob,'candidate generated bytes match importer: '+folder+'/'+name)
 before={str(p.relative_to(publish)):hashlib.sha256(p.read_bytes()).hexdigest() for p in publish.rglob('*') if p.is_file()}
 r=subprocess.run(['python3',root/'scripts/import-source-hit-animations.py',cache,publish],capture_output=True,text=True,timeout=30)
 after={str(p.relative_to(publish)):hashlib.sha256(p.read_bytes()).hexdigest() for p in publish.rglob('*') if p.is_file()}
 need(r.returncode!=0 and before==after,'CLI refuses existing output without modifying it')
 # Copy only importer+lock; tamper the lock without touching production inputs.
 local=temp/'importer';local.mkdir();(local/'import-source-hit-animations.py').write_bytes((root/'scripts/import-source-hit-animations.py').read_bytes());lock=bytearray((root/'scripts/source-hit-animation.lock.json').read_bytes());lock[20]^=1;(local/'source-hit-animation.lock.json').write_bytes(lock)
 r=subprocess.run(['python3',local/'import-source-hit-animations.py',cache,temp/'lock-output'],capture_output=True,text=True,timeout=30);need(r.returncode!=0 and not (temp/'lock-output').exists(),'modified authenticated input lock rejected before output')
result=dict(passed=True,checks=len(checks),details=checks,oversizedPeakBytes=peak,sourceCommit=imp.COMMIT,resources=[dict(path=folder+'/'+name,bytes=len(blob),sha256=hashlib.sha256(blob).hexdigest()) for folder,files in expected.items() for name,blob in files.items()]);(out/'result.json').write_text(json.dumps(result,indent=2)+'\n');print('PASS',len(checks),'source import checks')
